<template><ToolShell :eyebrow="label('Planning tool', 'Herramienta de planificación')" :title="label('Estimate an approved configuration', 'Estima una configuración aprobada')" :description="label('The result is non-binding and appears only when an owner-approved pricing model is configured.', 'El resultado no es vinculante y solo aparece cuando existe un modelo de precios aprobado.')"><form class="stack" @submit.prevent="run"><div class="form-grid"><BaseInput id="estimate-transactional" v-model="values.transactional_messages" name="transactional_messages" type="number" :label="label('Transactional messages / month', 'Mensajes transaccionales / mes')" /><BaseInput id="estimate-marketing" v-model="values.marketing_messages" name="marketing_messages" type="number" :label="label('Marketing messages / month', 'Mensajes de marketing / mes')" /><BaseInput id="estimate-profiles" v-model="values.profiles" name="profiles" type="number" :label="label('Profiles', 'Perfiles')" /><BaseInput id="estimate-seats" v-model="values.seats" name="seats" type="number" :label="label('Seats', 'Usuarios')" /></div><BaseButton type="submit" :disabled="pending">{{ pending ? label('Calculating…', 'Calculando…') : label('Calculate estimate', 'Calcular estimación') }}</BaseButton><BaseAlert v-if="errorMessage" tone="danger">{{ errorMessage }}</BaseAlert><BaseAlert v-if="result" :tone="result.status === 'estimated' ? 'success' : 'info'"><template v-if="result.status === 'estimated'">{{ label('Estimated monthly amount', 'Monto mensual estimado') }}: {{ result.currency }} {{ result.monthly_estimate }}</template><template v-else>{{ label('Approved prices are not configured. Request a pricing consultation instead.', 'No hay precios aprobados configurados. Solicita una consulta de precios.') }}</template></BaseAlert></form></ToolShell></template>
<script setup lang="ts">interface Result { status: string; currency?: string; monthly_estimate?: number } const { locale } = useLocale(); const label = (en:string,es:string)=>locale.value==='es'?es:en; const values=reactive({transactional_messages:'',marketing_messages:'',profiles:'',seats:''}); const result=ref<Result>(); const {pending,errorMessage,execute}=useToolRequest(); const run=async()=>{result.value=await execute<Result>('/api/v1/tools/pricing-estimate',{...values})}</script>
<style scoped>.form-grid { display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem }@media(max-width:36rem){.form-grid{grid-template-columns:1fr}}</style>
